#include "gfx/ps2x_ui.h"#include "gfx/video_state.h"#include "gfx/d3d11/ui_d3d11.h"#include "gfx/bt3gl_api.h"   // [B] bt3* API bridge#include "imgui.h"#include "rlImGui.h"#include "imgui_impl_opengl3.h"#include <cstdio>#include <cstdlib>namespace ps2x::gfx{    // Feed raylib's mouse/keyboard state into ImGui. imgui_impl_dx11 only renders; input    // is ours because raylib owns the window proc (we cannot hook a Win32 WndProc).    static void feedImGuiInput()    {        ImGuiIO &io = ImGui::GetIO();        // imgui_impl_dx11 does not set the display size (that is imgui_impl_win32's job,        // and we do not use it). Without this ImGui keeps its default (-1,-1) and clips        // every window to nothing. raylib owns the window, so read it from there; the        // D3D11 back buffer matches the client size 1:1.        io.DisplaySize = ImVec2((float)bt3GetScreenWidth(), (float)bt3GetScreenHeight());        io.DisplayFramebufferScale = ImVec2(1.0f, 1.0f);        const bt3Vector2 mp = bt3GetMousePosition();        io.AddMousePosEvent(mp.x, mp.y);        io.AddMouseButtonEvent(0, bt3IsMouseButtonDown(BT3_MOUSE_BUTTON_LEFT));        io.AddMouseButtonEvent(1, bt3IsMouseButtonDown(BT3_MOUSE_BUTTON_RIGHT));        io.AddMouseButtonEvent(2, bt3IsMouseButtonDown(BT3_MOUSE_BUTTON_MIDDLE));        const bt3Vector2 wheel = bt3GetMouseWheelMoveV();        io.AddMouseWheelEvent(wheel.x, wheel.y);        int c = 0;        while ((c = bt3GetCharPressed()) > 0)            io.AddInputCharacter(static_cast<unsigned>(c));        auto key = [&](int rl, ImGuiKey im) { io.AddKeyEvent(im, bt3IsKeyDown(rl) != 0); };        key(BT3_KEY_ESCAPE, ImGuiKey_Escape);        key(BT3_KEY_ENTER, ImGuiKey_Enter);        key(BT3_KEY_TAB, ImGuiKey_Tab);        key(BT3_KEY_BACKSPACE, ImGuiKey_Backspace);        key(BT3_KEY_DELETE, ImGuiKey_Delete);        key(BT3_KEY_RIGHT, ImGuiKey_RightArrow);        key(BT3_KEY_LEFT, ImGuiKey_LeftArrow);        key(BT3_KEY_UP, ImGuiKey_UpArrow);        key(BT3_KEY_DOWN, ImGuiKey_DownArrow);        key(BT3_KEY_HOME, ImGuiKey_Home);        key(BT3_KEY_END, ImGuiKey_End);        key(BT3_KEY_PAGE_UP, ImGuiKey_PageUp);        key(BT3_KEY_PAGE_DOWN, ImGuiKey_PageDown);        key(BT3_KEY_LEFT_SHIFT, ImGuiKey_LeftShift);        key(BT3_KEY_RIGHT_SHIFT, ImGuiKey_RightShift);        key(BT3_KEY_LEFT_CONTROL, ImGuiKey_LeftCtrl);        key(BT3_KEY_RIGHT_CONTROL, ImGuiKey_RightCtrl);        key(BT3_KEY_LEFT_ALT, ImGuiKey_LeftAlt);        key(BT3_KEY_RIGHT_ALT, ImGuiKey_RightAlt);        // ImGuiKey_A..Z and ImGuiKey_0..9 are contiguous in ImGui; raylib's BT3_KEY_A..Z and        // BT3_KEY_ZERO..NINE are too.        for (int k = 0; k < 26; ++k)            io.AddKeyEvent(static_cast<ImGuiKey>(ImGuiKey_A + k), bt3IsKeyDown(BT3_KEY_A + k) != 0);        for (int k = 0; k < 10; ++k)            io.AddKeyEvent(static_cast<ImGuiKey>(ImGuiKey_0 + k), bt3IsKeyDown(BT3_KEY_ZERO + k) != 0);    }    // [C] The overlay uses imgui_impl_opengl3 (its own GL loader + font atlas) instead of    // rlImGui/rlgl when the GL path is ours (PS2X_ALTGL=1). PS2X_UIGL overrides the choice:    //   1  -> always GL overlay        0 -> always rlImGui    //   unset -> GL overlay iff PS2X_ALTGL=1    static bool UiGlEnabled()    {        static const int s = [](){            const char *v = std::getenv("PS2X_UIGL");            if (v && v[0]) return (v[0] != '0') ? 1 : -1;            const char *a = std::getenv("PS2X_ALTGL");            return (a && a[0] && a[0] != '0') ? 1 : 0;        }();        return s > 0;    }    void UiSetup()    {        if (NativeVideo())            UiD3D11Init(*VideoDevice());        else if (UiGlEnabled())        {            // imgui_impl_opengl3 does NOT create the ImGui context (rlImGuiSetup used to do it            // for us), and ImGui::NewFrame on a null context is what crashed the runner.            ImGui::CreateContext();            ImGuiIO &io = ImGui::GetIO();            io.DisplaySize = ImVec2((float)bt3GetScreenWidth(), (float)bt3GetScreenHeight());            io.DisplayFramebufferScale = ImVec2(1.0f, 1.0f);            const bool ok = ImGui_ImplOpenGL3_Init("#version 330");            std::fprintf(stderr, "[uigl] imgui_impl_opengl3 init=%d (context created)\n", (int)ok);        }        else            rlImGuiSetup(true);    }    void UiBegin()    {        if (NativeVideo())        {            UiD3D11NewFrame();            feedImGuiInput();            ImGui::NewFrame();        }        else if (UiGlEnabled())        {            feedImGuiInput();            ImGui_ImplOpenGL3_NewFrame();            ImGui::NewFrame();        }        else        {            rlImGuiBegin();        }    }    void UiEnd()    {        if (NativeVideo())            UiD3D11Render();   // ImGui::Render() + ImGui_ImplDX11_RenderDrawData()        else if (UiGlEnabled())        {            // rlgl is still alive: flush the batch so our raw-GL overlay draws on top of it, then            // hand the state back through rlgl's own API (rlgl caches blend/program/texture and            // only re-applies what it thinks changed -- the same trap as the present).            bt3rlDrawRenderBatchActive();            ImGui::Render();            ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());            bt3rlEnableColorBlend();            bt3rlSetBlendMode(BT3RL_BLEND_ALPHA);            bt3rlActiveTextureSlot(0);            bt3rlDisableTexture();            bt3rlDisableShader();            bt3rlDrawRenderBatchActive();        }        else            rlImGuiEnd();    }    void UiShutdown()    {        if (NativeVideo())            UiD3D11Shutdown();        else if (UiGlEnabled())            ImGui_ImplOpenGL3_Shutdown();        else            rlImGuiShutdown();    }    void UiDrawTestWindow()    {        UiBegin();        ImGui::Begin("D3D11 UI test");        ImGui::Text("ImGui over D3D11 OK: %.1f fps", ImGui::GetIO().Framerate);        ImGui::End();        if (NativeVideo())            UiD3D11Render();   // ImGui::Render() + ImGui_ImplDX11_RenderDrawData()        else if (UiGlEnabled())        {            bt3rlDrawRenderBatchActive();            ImGui::Render();            ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());        }        else            rlImGuiEnd();        ImDrawData *dd = ImGui::GetDrawData();        static int n = 0;        if (n++ < 3)        {            const ImGuiIO &io = ImGui::GetIO();            std::fprintf(stderr, "[uitest] display=%.0fx%.0f fbScale=%.2fx%.2f valid=%d cmdlists=%d vtx=%d\n",                         io.DisplaySize.x, io.DisplaySize.y, io.DisplayFramebufferScale.x, io.DisplayFramebufferScale.y,                         (int)(dd && dd->Valid), dd ? dd->CmdListsCount : -1, dd ? dd->TotalVtxCount : -1);        }    }}